　「そこ、指づかい変えたほうがいいよ」
　言ってしまってから、心臓が鳴った。綿貫は顔を上げ、「教えてください」と言った。玲は鍵盤の前にすわり、その小節だけを弾いた。指は、思ったより動いた。
