        heading: 'つないで確かめる',
        body: `出来事の流れをつかむには、並べるだけでなくつなぐ必要がある。使う道具は二つだけでよい。

■ 「だから」でつながる場合（順接）
前の出来事が、次の出来事の原因になっている。
例）「ミスをして先輩に怒られた。だから、練習に行くのが憂うつになった。」
自然な流れなので、読者は立ち止まらない。

■ 「しかし」でつながる場合（逆接）
前の出来事から予想されることと、実際に起きたことがちがう。
例）「ミスをして先輩に怒られた。しかし、次の日もいちばんに練習に来た。」
ここで読者は「なぜ」と立ち止まる。作者はわざとそう書いている。つまり、逆接でしかつながらない箇所こそ、その人物の性格や思いが最も表れる場所である。

■ 実際の手順
①場面ごとの出来事を短く書き出す
②となりどうしを「だから」でつないでみる
③つながらないところに「しかし」を入れ、そこに印をつける
④印の箇所について「なぜそうしたのか」を本文から探す

例）
①伴奏に立候補しなかった → だから → ②綿貫が伴奏に決まった
②綿貫の下手な練習を毎日聞いていた → しかし → ③音楽室の戸を開けて助言した
この③が逆接である。聞いているだけだった人物が動いた。だからここが山場であり、設問が集まる。

★ ポイント：逆接の箇所を見つけたら、その直前の一〜二行を必ず読み返す。「聞いていられなくなって」のような、行動の理由が小さく書きこまれている。`,
