　弁当箱のふたを開けると、卵焼きが入っていた。焦げている。母の卵焼きはいつも少し焦げる。
　中学に入ってから、颯太は友達と学食に行くようになった。弁当はいらないと何度も言った。それでも母は毎朝作った。作るなと言うと、母は「作りたいから作ってるの」と言って、それきり話は終わる。
