        body: `次の文章の傍線部（行動描写）を、手順で読んでみる。

　夕食のあいだ、母は二度、時計を見た。父の帰りが遅い。
　「先に食べなさい」と母が言った。芽依は箸を取ったが、みそ汁を一口飲んで、置いた。
　「おなか、すいてない？」
　「うん」
　母は立ち上がり、台所でなにかを片づけはじめた。片づけるものは、もうほとんどなかった。水を出し、止め、また出した。
　九時をすぎて、玄関の音がした。父が帰ってきた。母は流しに立ったまま、振り返らずに「ごはん、ある」と言った。声はいつもより少し高かった。
　父が「ああ」と答えたとき、母はようやく蛇口を止めた。芽依は、冷めたみそ汁をもう一度あたためた。

■ 動作を拾って、なぜかを問う
・母が二度時計を見た → 型③（くり返す）→ 父の帰りが気になって落ち着かない
・芽依がみそ汁を一口飲んで箸を置いた → 型①（中断）→ 母の様子が気になり食欲がわかない
・母が片づけるものもないのに片づけ、水を出し止めした → 型③ → 心配を紛らわせている。何かしていないといられない
・振り返らずに話した → 型② → 心配していたことを見せたくない、あるいは腹立ちもある
・声が少し高かった → 平静を装いきれていない
・父の返事を聞いて蛇口を止めた → 心配が解けた合図。ここまでずっと水を出していたことが、緊張の持続を表す

■ 全体の読み
この場面には「心配」という語も「安心」という語も出てこない。それでも、動作の連なりだけで母の緊張と安堵がはっきり描かれている。最後に芽依がみそ汁をあたため直すのは、家族の時間がようやく動きだしたことを示す。

⚠ 注意：「水を出し、止め、また出した」を、単なる家事の描写として読み飛ばさないこと。意味のない反復が書かれているときは、必ず心情の描写である。作者は無駄な文を書かない。`,
