        heading: '本文で確かめる',
        body: `次の文章で、体の反応を拾いながら読んでみる。

　名前を呼ばれて、和樹は立ち上がった。前に出るまでの十歩ほどが、やけに長かった。手のひらが汗ばんでいるのが分かる。原稿を持つ指先が、細かく震えていた。
　演台に立って、和樹は一度、息を止めた。それから顔を上げた。体育館の後ろのほうまで、人の頭が並んでいる。二年生の列に、去年、同じ班だった榊原がいるのが見えた。榊原はこちらを見ていた。
　「ぼくは、去年の秋まで、この学校に来るのが嫌でした」
　声が思ったより出た。自分の声が体育館に返ってくるのを聞いて、和樹はつばを飲みこみ、次の行を読んだ。震えは、いつのまにか止まっていた。
　読み終えて席にもどるとき、膝の力が抜けそうになった。拍手の音は、耳の奥のほうで聞こえていた。

■ 拾った反応と意味
・十歩が長く感じられた……主観的な時間の伸び＝極度の緊張
・手のひらが汗ばむ／指先が震える……緊張（あふれた反応）
・息を止めた……集中、覚悟の直前（抑えた反応）
・つばを飲みこむ……緊張の中で次へ進む合図
・震えが止まった……緊張が和らいだ＝話しはじめて落ち着いた
・膝の力が抜けそうになった……終わったことによる解放
・拍手が耳の奥で聞こえた……まだ現実感が戻っていない＝放心

■ 心情の流れ
極度の緊張 → 覚悟 → 話し出して落ち着く → 終えて放心と安堵
体の反応だけをたどると、この四段階がそのまま出てくる。「緊張した」「安心した」という語は一つも使われていないのに、である。

■ 設問に使う
「震えは、いつのまにか止まっていた」の心情を問われたら、「自分の言葉が届いていると感じられ、緊張がやわらいで落ち着きを取り戻している」と答える。「いつのまにか」は、本人が意識しないうちに変化したことを示すので、「意識せずに」「気づかないうちに」という要素を入れると正確になる。

⚠ 注意：「拍手の音は、耳の奥のほうで聞こえていた」を「拍手が小さかった」と読まないこと。音の聞こえ方が変わるのは、本人の感覚の側の問題である。放心状態や高揚状態では、音が遠く感じられる。感覚の描写は、外の事実ではなく心の状態を表す。`,
