        heading: '話者を確定する四つの手がかり',
        body: `会話文の話者は、次の手がかりで確定する。

■ ①交互の原則
二人の会話は、原則として交互に進む。まず一行おきに人物名を書きこむ。
ただし、同じ人物が続けて二回話すこともある。その場合は必ず、間に地の文（動作の描写など）が入るか、話題が変わる合図がある。

■ ②「と、〜は言った」を基準にする
本文中に一つでも話者が明示された行があれば、そこを起点にする。
例）三行目に「と、母は言った」とあれば、三行目＝母、二行目＝相手、四行目＝相手、と広げていける。

■ ③呼びかけの言葉
「お母さん、あのさ」と言えば、話しているのは子である。
「先輩、これ」と言えば、話しているのは後輩である。
呼びかけは、相手ではなく話し手を教えてくれることに注意する。

■ ④口調の特徴
敬語を使う／使わない、方言、語尾（〜だろ／〜でしょ／〜じゃん）、一人称（ぼく・おれ・わたし・うち）。
一度その人物の口調をつかめば、話者名がなくても判別できる。長い会話の場面では、これが決め手になる。

■ 独白との区別
かぎかっこがない文で「なぜ言ってしまったのだろう」のように書かれていれば、それは口に出したせりふではなく心の中の言葉である。相手には聞こえていない。ここを声に出したと読むと、話の展開がおかしくなる。

★ ポイント：三人以上の会話では、必ず余白に人物名の頭文字を書く。「母・芽・父」のように一文字で十分。書かずに頭の中だけで追うと、必ずどこかでずれる。`,
