        heading: '色彩の読み方',
        body: `色の描写は、場面の空気を短く伝える。

■ 基本の対応
・赤、オレンジ、金……熱、活気、夕日の温かさ、あるいは興奮
・青、水色……涼しさ、静けさ、澄んだ気持ち、あるいは冷たさ
・緑……生命力、成長、若さ
・白……清らかさ／空白・無／冷たさ。場面で三通りに分かれる
・灰色……沈滞、はっきりしない気持ち
・黒……不安、拒絶、重さ

■ 色の変化に注目
・「あせた」「色が抜けた」……時間の経過、思い出の古さ
・「色が戻る」……気力の回復
・「白く飛ぶ」「目の前が白くなる」……衝撃で何も考えられない
・「まわりが灰色に見えた」……気力の喪失。実際の色ではなく、その人の見え方である

■ 色の対比
一つの場面に二つの色を並べる書き方は、対比を作る。
例）「教室の白い壁に、体操服の赤いゼッケンだけが浮いて見えた。」
白＝無機質な背景、赤＝目立つ存在。この対比は、その人物が周囲から浮いていることを示す。

■ 使い方
色の描写を見つけたら、次の二点を確かめる。
①その色は、人物の気持ちと同じ向きか、逆向きか
②その色を「見ている」のはだれか。視点人物が見ているなら、色の印象はその人物の心を映している

★ ポイント：色は主観である。「空が灰色だった」と書かれていても、実際の空の色ではなく、その人物にはそう見えたという意味かもしれない。とくに「〜に見えた」がついていれば、確実に主観である。`,
