        heading: '季節と時刻の意味',
        body: `季節と時刻には、共有された意味がある。

■ 季節
・春……出会い、始まり、進級・入学。ただし別れ（卒業）の季節でもある。桜は美しさと同時に「散る」ものとして扱われる。
・夏……熱、盛り、大会、成長。中学生の物語では「最後の夏」が特別な意味を持つ。入道雲・蝉の声・夕立が定番の道具。
・秋……実り、静けさ、寂しさ、終わりの予感。日が短くなること自体が終わりを感じさせる。
・冬……耐える時期、受験、別れ、静けさ。雪は音を消す。

■ 時刻
・朝……始まり、決意、まだ何も起きていない状態
・昼……日常、周囲に人がいる、平常心
・夕方……一日の終わり、名残惜しさ、感傷。西日は温かさと同時に「終わり」を示す
・夜……一人になる時間、内省、本音、不安
・深夜・明け方……孤独が最も強い時間。明け方は、そこから始まる転換の合図

■ 意味づけを読む
本文が「中学最後の夏」と書けば、それは単なる季節ではなく「もう次がない」という意味になる。同じ夏でも、一年生の夏なら「まだ二回ある」という意味である。人物にとっての意味づけを必ず読み取る。

■ 時間の経過を示す道具
・木の葉の色、花、虫の声、日の長さ、服装、空気の温度
これらが変われば、時間が経過したことが分かる。場面と場面のあいだの時間の隔たりを、季節の道具で示すのは常套手段である。

★ ポイント：季節と時刻を確認したら、「なぜこの季節・この時刻でなければならないのか」を一度考える。答えが出れば、その場面の意味がつかめている。`,
