        heading: '本文で読む',
        body: `次の文章で、ずれを読み取ってみよう。

　合格発表の日、空はよく晴れていた。桜にはまだ早いが、校門のあたりは人でいっぱいだった。番号を見つけた人が声を上げ、抱き合っている。カメラを構えている親もいる。
　颯は、掲示板を三度見た。自分の番号はなかった。三度目は、上から順に指でたどった。それでも、なかった。
　人の声が、遠くなった。だれかが背中にぶつかって「すみません」と言った。颯は「いえ」と答えた。自分の声が、他人のもののように聞こえた。
　校門を出ると、通りはいつもどおりだった。信号は変わり、バスは来て、店は開いている。何も変わっていない。世界のほうは、何も変わっていない。
　バス停で、颯は一度だけ空を見た。あいかわらず、よく晴れていた。晴れていることが、少し腹立たしかった。

■ ずれを取り出す
・晴れた空／喜ぶ人々 × 不合格の颯……パターン①。周囲の明るさが、自分の落胆を際立たせる。
・「人の声が、遠くなった」……音の描写。衝撃で現実感が失われている。
・「通りはいつもどおりだった」「世界のほうは、何も変わっていない」……パターン③。自分に大きなことが起きても、世界は無関心に動いている。
・「晴れていることが、少し腹立たしかった」……ずれを人物自身が意識した一文。ここが最も重要である。

■ 「腹立たしかった」の読み
天気に腹を立てるのは筋違いである。それでもそう感じるのは、自分の落ちこみとまったく釣り合わない明るさが、そこにあるからである。つまりこの一文は、天気への怒りではなく、落胆の深さを示している。

■ 解答例
問「『晴れていることが、少し腹立たしかった』とあるが、このときの颯の心情を説明しなさい。」
解答例：「不合格の落胆で沈んでいるのに、周囲の空も町も何ごともなかったように明るく変わらないことに、自分だけが取り残されたようなやるせなさを覚えている。」

⚠ 注意：「天気が悪いと感じている」「晴れが嫌いだ」と書いてはいけない。情景への感情は、必ず人物の状況に置きかえて説明する。情景そのものへの好き嫌いを答える設問は存在しない。`,
