        body: `きっかけを特定する手順を決めておく。

■ 手順
①変化後の心情がどこに書かれているかを確定する（多くは結末付近）
②そこから前へさかのぼり、心情が変化前のままである最後の箇所を探す
③②と①のあいだにある出来事が、きっかけの候補である
④候補が複数あれば、変化後の内容と直接つながるものを選ぶ

■ ④の判定方法
変化後の心情を一言で言い、その内容に対応する候補を選ぶ。
例）変化後＝「一人で背負わなくてよいと感じた」
候補A＝「もういいじゃん」という声（否定された出来事。変化後の内容と逆向き）
候補B＝井上の「わたしも同じところで外すの」（同じ悩みを共有する内容。直接つながる）
→ Bが正解。

■ 決定的な語
次の語があれば、そこが変化の瞬間である。
・「そのとき初めて」「はじめて〜と思った」
・「〜と、そのとき気づいた」
・「急に」「ふいに」「不意に」
・「もう〜ではなかった」
これらの語の直前に、きっかけがある。

■ 抜き出し問題の注意
・字数条件（十五字以内、一文で、など）を必ず確認する
・「〜こと」で終わる形が指定されていれば、その形になる部分を選ぶ
・句読点を字数に含めるかは問題の指示に従う。指示がなければ含める
・抜き出しは一字一句正確に。勝手に語尾を変えない

★ ポイント：候補が二つに絞れて迷ったら、「その出来事がなかったら、変化は起きたか」と自問する。起きたと思えるほうは、きっかけではない。`,
