        body: `選択問題では、次の三種類の誤答が混ざる。見分け方を覚える。

■ 誤答型①：本文の一部だけを述べたもの
例）「部活動では先輩後輩の協力が大切であるということ。」
本文の一場面には当てはまるが、主人公の変化全体を説明していない。主題は物語全体を貫くものでなければならない。

■ 誤答型②：一般論として正しいが、本文と関係がないもの
例）「努力は必ず報われるということ。」
言葉としてはもっともらしいが、本文にそのような展開がなければ誤り。とくに、本文が努力の結果を描いていない場合は明確に誤答である。もっともらしい一般論に引かれないこと。

■ 誤答型③：本文と逆、または言いすぎのもの
例）「他人の評価こそが、表現の価値を決めるということ。」
莉子の変化と逆向きである。また「〜こそがすべてだ」のような断定は、文学作品の主題としては強すぎる。

■ 正解の形
・主人公の変化の方向と一致している
・物語全体を説明できる
・断定しすぎず、「〜に気づく」「〜の大切さ」といった形になっている

■ 手順
①自分で主題を一言作る（選択肢を見る前に）
②その内容に最も近い選択肢を選ぶ
③残った選択肢が、上の三型のどれに当たるかを確認して切る

自分で作ってから選ぶのが重要である。先に選択肢を読むと、もっともらしい文に引きずられる。

⚠ 注意：題名が示されている場合は必ず利用する。「あの日の縄跳び」という題名なら、縄跳びをめぐる母との記憶が主題に関わると分かる。題名と無関係な選択肢は、疑ってかかる。`,
