        heading: '書き方の細部',
        body: `型が決まっても、細部で失点することがある。注意点をまとめる。

■ ①主語をそろえる
「はじめは詩織が〜だったが、クラスメイトが案を書いたことで、詩織は〜」
主語が二度変わると読みにくい。「クラスメイトが案を書いてくれたことで」と、きっかけ部分を修飾句に収めると、主語は詩織のまま保てる。

■ ②比喩・慣用句を開く
本文「胸のつかえが下りた」→ 解答「わだかまりが解けて気持ちが軽くなった」
本文「肩の荷が下りた」→ 解答「責任から解放されて楽になった」
そのまま写すと、理解を示せない。

■ ③文末を設問に合わせる
・「どのような気持ちか」→「〜という気持ち。」
・「なぜか」「理由を答えよ」→「〜から。」「〜ため。」
・「どのように変わったか」→「〜から〜に変わった。」「〜と思うようになった。」
文末が対応していないだけで減点する学校がある。必ず設問文を見返す。

■ ④断定しすぎない
本文が「来年は、と思った」で止まっているなら、「立ち直った」「克服した」と書かない。「前向きな気持ちが芽生えはじめた」と程度を合わせる。

■ ⑤指示語を残さない
「そのこと」「それ」を解答に使わない。何を指すかを書く。解答は単独で読んで意味が通らなければならない。

■ ⑥見直しの手順
書き終えたら、次の三点を指でさして確認する。
（1）変化前が入っているか
（2）きっかけが入っているか
（3）変化後が入っているか
さらに、（4）文末が設問と対応しているか、（5）本文にない内容を書いていないか。
この五点確認を三十秒でやる習慣をつければ、記述の失点は大きく減る。

⚠ 注意：時間が足りないときでも、白紙にはしない。変化前と変化後だけでも書けば部分点が入る。逆に、完璧を目指して書き出せないのが最も損である。`,
